CREATE OR REPLACE FUNCTION nexus.gc_restore_rereferenced(dim integer, p_tenant_id text, p_quarantine_collection text, p_origin_collection text) RETURNS bigint LANGUAGE plpgsql AS $function$ DECLARE v_origin_id bigint; v_quar_id bigint; -- RDR-229 P3.7 (vectors-083): read once, at the top of the call; from gate 3 a quarantined chunk is the origin's by the origin's id v_latched boolean := EXISTS (SELECT 1 FROM nexus.rdr229_gate_latch WHERE gate = 'gate3'); v_chashes bytea[]; v_restored bigint := 0; v_row_count bigint := 0; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection; SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection; IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_restore_rereferenced: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND CASE WHEN v_latched THEN c.metadata->'origin_collection_id' = to_jsonb(v_origin_id) ELSE COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection END AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> '')) AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN 0; END IF;
-- N7-STYLE cross-dim collision guard (Critical-1 fix, T2 [22454]): -- same reasoning as gc_quarantine_orphans's guard -- detect, BEFORE -- any row moves, any restore candidate whose chash already exists at -- p_origin_collection under a DIFFERENT populated embedding_<dim> -- column than the candidate's own. WITH candidate AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes) ), collision AS ( SELECT cand.chash, cand.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM candidate cand JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND (e.collection_id = v_origin_id OR (e.collection_id IS NULL AND e.collection = p_origin_collection AND p_origin_collection <> '')) AND e.chash = cand.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced: % cross-dim (tenant_id, collection, chash) collision(s) at restore target % for tenant=%, quarantine collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the origin-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_origin_collection, p_tenant_id, p_quarantine_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- RDR-204 nexus-uxd2a (hygiene-005-2): NO ENGINE PATH DERIVES A -- COLLECTION'S ATTRIBUTES FROM ITS NAME (coordinator nexus-71 decision, -- same as gc_quarantine_orphans above). p_origin_collection's own name -- usually parsed correctly here (it never carries the quarantine- -- prefix), but deriving from a name is still fragile by construction -- -- an origin name outside the four name-shape branches (hygiene-004's -- underscored-owner class, a two-segment grandfathered name, or -- anything unparseable) silently fell to the 'unknown' stub with no -- dimension ever recorded. This self-registration is a DELIBERATE -- CARVE-OUT (PgVectorRepository.restoreRereferenced's own javadoc, -- RDR-204 Phase 2 nexus-ft04v.16): a genuinely first-ever origin -- collection is still minted here, from real, known attributes -- now -- copied from the QUARANTINE collection's own row rather than parsed -- from either name, since p_quarantine_collection is REQUIRED to -- already be registered (PgVectorRepository.restoreRereferenced -- resolves dim from it before ever reaching this function) and both -- collections share the same embedding space by construction (restore -- only ever moves a chunk between the two). An existing origin row is -- left exactly as it is (ON CONFLICT DO NOTHING) -- only a genuinely -- first-ever origin is minted from the quarantine row's attributes. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_quarantine_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_restore_rereferenced: quarantine collection % is not registered for tenant % -- attributes for a first-ever origin registration are copied from the quarantine row, never parsed from either name (RDR-204 nexus-uxd2a)', p_quarantine_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_origin_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'live' ) ON CONFLICT (tenant_id, name) WHERE superseded_by = '' AND superseded_by_id IS NULL DO NOTHING;
-- The origin's id is read again now that it is registered: a first-ever origin had none when the body began, and a -- racing registration (the DO NOTHING above) may have committed one since. SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection;
-- created_at CARRIED THROUGH (nexus-e8h5x review round 2, mirroring -- catalog-037's fix for the opposite direction): the pre-fix INSERT -- omitted it, so the default restamped every restored row to restore -- time and destroyed the chunk's generation history across the -- quarantine round trip. -- RDR-225: embedding_model rides with the row (the chunk's own model, never the origin collection's: an -- origin registered under another model refuses the row at the composite foreign key instead of filing a -- vector under a model that did not embed it); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model, collection_id) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, -- RDR-236 (nexus-6pfgb.40): the restored row holds only the CHUNK keys of the key table. The four quarantine keys -- (quarantined_at, origin_collection, quarantined_by, reaper_quarantined_at) are the physical row's, written by the -- engine's two quarantine moves, and every other key is a document or position key whose home is the catalog. -- Both are derived from the columns, so the Phase 4 equalities hold by construction. jsonb_build_object('chunk_text_hash', encode(c.chash, 'hex'), 'embedding_model', c.embedding_model), c.created_at, c.embedding_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection) FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes) -- target-less: absorbs the name key and the id twin alike (RDR-229 P3.5b, two unique keys until P4.1) ON CONFLICT DO NOTHING;
-- nexus-brxnp fix round: rows genuinely inserted vs. rows skipped -- because the origin already had a live row for that chash (the DO -- NOTHING conflict) -- recorded below as `already_live` so a -- production investigation can tell the two apart without re-deriving -- it from chunk timestamps by hand (T2 nexus/debug-u6d93-brxnp). GET DIAGNOSTICS v_row_count = ROW_COUNT;
DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> '')) AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1);
-- nexus-gt03d: audit the restore IN THE SAME TRANSACTION as the DELETE -- above -- this is the exact gap conexus-86/nexus-9la1f found: rows -- leaving quarantine by restore had no forensic trail, unlike -- gc_quarantine_orphans/sweep_superseded_chunks (catalog-033). -- `chashes` here is v_chashes itself (no caller-supplied sample_limit -- on this function, unlike gc_quarantine_orphans -- same shape as -- gc_expire_quarantine's own audit above), truncated at -- GC_AUDIT_MAX_CHASHES (5000, CatalogRepository.java) with -- chash_count still carrying the exact full v_restored count -- regardless of truncation. nexus-brxnp fix round: also -- already_live = candidates that hit the DO NOTHING conflict. INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_restore_rereferenced', p_quarantine_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection), 'engine', false, v_restored, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_chashes[1:LEAST(COALESCE(array_length(v_chashes, 1), 0), 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'already_live', v_restored - v_row_count) || CASE WHEN COALESCE(array_length(v_chashes, 1), 0) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END );
RETURN v_restored; END; $function$;

